const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const crypto = require('crypto');
const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const commitSha = String(payload.commitSha || payload.commit || 'head-sync').trim();
const branch = String(payload.branch || 'main').trim();
const author = String(payload.author || 'system-sync').trim();
const repository = String(payload.repository || 'logic-intelligence-technologies').trim();
const syncType = String(payload.syncType || 'git_push').trim();

const rawFiles = Array.isArray(payload.modifiedFiles || payload.files) ? (payload.modifiedFiles || payload.files) : [
  {
    path: 'docs/architecture/system-overview.md',
    content: '# System Overview\nLogic Intelligence Technologies platform architecture specifications and enterprise design rules.',
    category: 'architecture'
  },
  {
    path: 'src/lib/ai/company-knowledge.ts',
    content: 'export const companyFacts = { mission: "Enterprise AI and Full-Stack Engineering Orchestration", lead: "Vikash Saravanan" };',
    category: 'company-knowledge'
  }
];

const processedChunks = [];
let totalWords = 0;

for (const file of rawFiles) {
  const filePath = String(file.path || 'unknown.md');
  const rawContent = String(file.content || '');
  const category = String(file.category || (filePath.includes('docs/') ? 'docs' : 'codebase'));

  const paragraphs = rawContent.split(/\n\n+/).filter(p => p.trim().length > 0);
  let chunkIndex = 0;
  for (const para of paragraphs) {
    const text = para.trim();
    const words = text.split(/\s+/).length;
    totalWords += words;
    const chunkHash = crypto.createHash('sha256').update(text).digest('hex');
    const chunkId = `chk_${chunkHash.substring(0, 16)}`;

    processedChunks.push({
      chunkId,
      filePath,
      category,
      chunkIndex,
      wordCount: words,
      estimatedTokens: Math.ceil(words * 1.33),
      contentSnippet: text.substring(0, 200),
      contentHash: chunkHash,
      commitSha,
      lastModified: new Date().toISOString()
    });
    chunkIndex++;
  }
}

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    syncMeta: {
      commitSha,
      branch,
      author,
      repository,
      syncType,
      fileCount: rawFiles.length,
      chunkCount: processedChunks.length,
      totalWords
    },
    chunks: processedChunks
  }
}];

const item = $input.first().json;
const meta = item.syncMeta;
const chunks = item.chunks || [];

const vectorStoreTable = 'rag_documents';
const embeddingModel = 'text-embedding-3-small';
const vectorDimensions = 1536;

const upsertBatch = chunks.map(c => ({
  id: c.chunkId,
  document_path: c.filePath,
  category: c.category,
  chunk_index: c.chunkIndex,
  token_count: c.estimatedTokens,
  content_hash: c.contentHash,
  vector_dimensions: vectorDimensions,
  model: embeddingModel,
  embedding_status: 'embedded',
  synced_at: new Date().toISOString()
}));

const cacheInvalidations = [
  'rag:knowledge_base',
  'rag:company_facts',
  'rag:system_prompts'
];

const syncSummary = {
  status: 'SUCCESS',
  repository: meta.repository,
  commitSha: meta.commitSha,
  filesProcessed: meta.fileCount,
  totalChunksCreated: chunks.length,
  totalEstimatedTokens: chunks.reduce((acc, c) => acc + c.estimatedTokens, 0),
  vectorStoreTable,
  embeddingModel,
  vectorDimensions,
  upsertedCount: upsertBatch.length,
  cacheInvalidated: true,
  invalidatedKeys: cacheInvalidations,
  syncedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'ops.knowledge_synced',
    detail: {
      syncSummary,
      records: upsertBatch.slice(0, 10)
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'ops.knowledge_synced',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
